/**
 * Auto-resize utilities for thumbnail URLs
 * Automatically generates optimized image URLs for different screen sizes and use cases
 */
import React from 'react';

export interface AutoResizeConfig {
  width?: number;
  height?: number;
  quality?: number;
  format?: 'webp' | 'jpg' | 'png' | 'auto';
  fit?: 'crop' | 'fill' | 'contain' | 'cover';
}

export interface ResponsiveSizes {
  small: string;    // 280px width - mobile cards
  medium: string;   // 400px width - tablet cards  
  large: string;    // 600px width - desktop cards
  xlarge: string;   // 800px width - modal thumbnails
}

/**
 * Detect image service provider from URL
 */
export const detectImageService = (url: string): 'unsplash' | 'ibb' | 'cloudinary' | 'generic' => {
  if (url.includes('unsplash.com')) return 'unsplash';
  if (url.includes('i.ibb.co') || url.includes('ibb.co')) return 'ibb';
  if (url.includes('cloudinary.com')) return 'cloudinary';
  return 'generic';
};

/**
 * Generate auto-resized URL for Unsplash images
 */
export const generateUnsplashResize = (url: string, config: AutoResizeConfig): string => {
  const baseUrl = url.split('?')[0]; // Remove existing parameters
  const params = new URLSearchParams();
  
  if (config.width) params.set('w', config.width.toString());
  if (config.height) params.set('h', config.height.toString());
  if (config.quality) params.set('q', config.quality.toString());
  if (config.fit) params.set('fit', config.fit);
  if (config.format && config.format !== 'auto') params.set('fm', config.format);
  
  return `${baseUrl}?${params.toString()}`;
};

/**
 * Generate auto-resized URL for ImgBB images
 * Note: ImgBB doesn't support URL-based resizing, so we'll use client-side optimization
 */
export const generateIbbResize = (url: string, _config: AutoResizeConfig): string => {
  // ImgBB doesn't support URL parameters for resizing
  // We'll return the original URL and handle resizing client-side
  return url;
};

/**
 * Generate auto-resized URL for Cloudinary images
 */
export const generateCloudinaryResize = (url: string, config: AutoResizeConfig): string => {
  // Extract the base URL and add transformation parameters
  const parts = url.split('/upload/');
  if (parts.length !== 2) return url;
  
  const transformations: string[] = [];
  
  if (config.width) transformations.push(`w_${config.width}`);
  if (config.height) transformations.push(`h_${config.height}`);
  if (config.quality) transformations.push(`q_${config.quality}`);
  if (config.fit) transformations.push(`c_${config.fit}`);
  if (config.format && config.format !== 'auto') transformations.push(`f_${config.format}`);
  
  const transformationString = transformations.join(',');
  return `${parts[0]}/upload/${transformationString}/${parts[1]}`;
};

/**
 * Generate auto-resized URL based on image service
 */
export const generateAutoResizedUrl = (url: string, config: AutoResizeConfig): string => {
  const service = detectImageService(url);
  
  switch (service) {
    case 'unsplash':
      return generateUnsplashResize(url, config);
    case 'ibb':
      return generateIbbResize(url, config);
    case 'cloudinary':
      return generateCloudinaryResize(url, config);
    default:
      return url; // Return original URL for unknown services
  }
};

/**
 * Generate responsive sizes for a thumbnail URL
 */
export const generateResponsiveThumbnails = (url: string): ResponsiveSizes => {
  return {
    small: generateAutoResizedUrl(url, { 
      width: 280, 
      height: 158, 
      quality: 75, 
      fit: 'crop',
      format: 'auto'
    }),
    medium: generateAutoResizedUrl(url, { 
      width: 400, 
      height: 225, 
      quality: 80, 
      fit: 'crop',
      format: 'auto'
    }),
    large: generateAutoResizedUrl(url, { 
      width: 600, 
      height: 338, 
      quality: 85, 
      fit: 'crop',
      format: 'auto'
    }),
    xlarge: generateAutoResizedUrl(url, { 
      width: 800, 
      height: 450, 
      quality: 90, 
      fit: 'crop',
      format: 'auto'
    })
  };
};

/**
 * Generate srcSet string for responsive images
 */
export const generateAutoResizeSrcSet = (url: string): string => {
  const sizes = generateResponsiveThumbnails(url);
  
  return [
    `${sizes.small} 280w`,
    `${sizes.medium} 400w`, 
    `${sizes.large} 600w`,
    `${sizes.xlarge} 800w`
  ].join(', ');
};

/**
 * Generate sizes attribute for responsive images
 */
export const generateAutoResizeSizes = (): string => {
  return [
    '(max-width: 480px) 280px',
    '(max-width: 768px) 400px', 
    '(max-width: 1024px) 600px',
    '800px'
  ].join(', ');
};

/**
 * Client-side image resizing for services that don't support URL-based resizing
 */
export const resizeImageClientSide = (
  imageUrl: string, 
  targetWidth: number, 
  targetHeight: number,
  quality: number = 0.8
): Promise<string> => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    
    img.onload = () => {
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      
      if (!ctx) {
        reject(new Error('Canvas context not available'));
        return;
      }
      
      canvas.width = targetWidth;
      canvas.height = targetHeight;
      
      // Calculate scaling to maintain aspect ratio with crop
      const scale = Math.max(targetWidth / img.width, targetHeight / img.height);
      const scaledWidth = img.width * scale;
      const scaledHeight = img.height * scale;
      
      // Center the image
      const x = (targetWidth - scaledWidth) / 2;
      const y = (targetHeight - scaledHeight) / 2;
      
      ctx.drawImage(img, x, y, scaledWidth, scaledHeight);
      
      // Convert to data URL
      const resizedDataUrl = canvas.toDataURL('image/jpeg', quality);
      resolve(resizedDataUrl);
    };
    
    img.onerror = () => {
      reject(new Error(`Failed to load image: ${imageUrl}`));
    };
    
    img.src = imageUrl;
  });
};

/**
 * Auto-resize hook for React components
 */
export const useAutoResize = (originalUrl: string) => {
  const [resizedUrls, setResizedUrls] = React.useState<ResponsiveSizes | null>(null);
  const [isResizing, setIsResizing] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);
  
  React.useEffect(() => {
    const generateResizedUrls = async () => {
      try {
        setIsResizing(true);
        setError(null);
        
        const service = detectImageService(originalUrl);
        
        if (service === 'ibb') {
          // For ImgBB, generate client-side resized versions
          const [small, medium, large, xlarge] = await Promise.all([
            resizeImageClientSide(originalUrl, 280, 158),
            resizeImageClientSide(originalUrl, 400, 225),
            resizeImageClientSide(originalUrl, 600, 338),
            resizeImageClientSide(originalUrl, 800, 450)
          ]);
          
          setResizedUrls({ small, medium, large, xlarge });
        } else {
          // For other services, use URL-based resizing
          const responsive = generateResponsiveThumbnails(originalUrl);
          setResizedUrls(responsive);
        }
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to resize image');
        // Fallback to original URL
        setResizedUrls({
          small: originalUrl,
          medium: originalUrl,
          large: originalUrl,
          xlarge: originalUrl
        });
      } finally {
        setIsResizing(false);
      }
    };
    
    if (originalUrl) {
      generateResizedUrls();
    }
  }, [originalUrl]);
  
  return { resizedUrls, isResizing, error };
};

/**
 * Preload resized images for better performance
 */
export const preloadResizedImages = async (url: string): Promise<void> => {
  const sizes = generateResponsiveThumbnails(url);
  
  const preloadPromises = Object.values(sizes).map(resizedUrl => {
    return new Promise<void>((resolve, reject) => {
      const img = new Image();
      img.onload = () => resolve();
      img.onerror = () => reject(new Error(`Failed to preload: ${resizedUrl}`));
      img.src = resizedUrl;
    });
  });
  
  try {
    await Promise.allSettled(preloadPromises);
  } catch (error) {
    console.warn('Some resized images failed to preload:', error);
  }
};

/**
 * Get optimal image size based on container dimensions
 */
export const getOptimalImageSize = (
  containerWidth: number, 
  containerHeight: number,
  devicePixelRatio: number = window.devicePixelRatio || 1
): AutoResizeConfig => {
  const targetWidth = Math.ceil(containerWidth * devicePixelRatio);
  const targetHeight = Math.ceil(containerHeight * devicePixelRatio);
  
  // Choose quality based on device capabilities
  const quality = devicePixelRatio > 1 ? 85 : 75;
  
  return {
    width: targetWidth,
    height: targetHeight,
    quality,
    fit: 'crop',
    format: 'auto'
  };
};

/**
 * Cache for resized images to avoid regenerating
 */
class ImageResizeCache {
  private cache = new Map<string, ResponsiveSizes>();
  private maxSize = 100; // Maximum number of cached entries
  
  get(url: string): ResponsiveSizes | null {
    return this.cache.get(url) || null;
  }
  
  set(url: string, sizes: ResponsiveSizes): void {
    // Remove oldest entry if cache is full
    if (this.cache.size >= this.maxSize) {
      const firstKey = this.cache.keys().next().value;
      if (firstKey) {
        this.cache.delete(firstKey);
      }
    }
    
    this.cache.set(url, sizes);
  }
  
  clear(): void {
    this.cache.clear();
  }
  
  size(): number {
    return this.cache.size;
  }
}

export const imageResizeCache = new ImageResizeCache();

/**
 * Enhanced auto-resize function with caching
 */
export const getAutoResizedThumbnails = (url: string): ResponsiveSizes => {
  // Check cache first
  const cached = imageResizeCache.get(url);
  if (cached) {
    return cached;
  }
  
  // Generate new resized URLs
  const resized = generateResponsiveThumbnails(url);
  
  // Cache the result
  imageResizeCache.set(url, resized);
  
  return resized;
};