/**
 * Focus management utilities for accessibility
 */

/**
 * Gets all focusable elements within a container
 */
export const getFocusableElements = (container: HTMLElement): HTMLElement[] => {
  const focusableSelectors = [
    'a[href]',
    'button:not([disabled])',
    'input:not([disabled])',
    'select:not([disabled])',
    'textarea:not([disabled])',
    '[tabindex]:not([tabindex="-1"])',
    '[contenteditable="true"]'
  ].join(', ');

  return Array.from(container.querySelectorAll(focusableSelectors))
    .filter((element) => {
      const htmlElement = element as HTMLElement;
      return (
        htmlElement.offsetWidth > 0 &&
        htmlElement.offsetHeight > 0 &&
        !htmlElement.hidden &&
        window.getComputedStyle(htmlElement).visibility !== 'hidden'
      );
    }) as HTMLElement[];
};

/**
 * Traps focus within a container (useful for modals)
 */
export class FocusTrap {
  private container: HTMLElement;
  private focusableElements: HTMLElement[] = [];
  private firstFocusableElement: HTMLElement | null = null;
  private lastFocusableElement: HTMLElement | null = null;
  private previouslyFocusedElement: HTMLElement | null = null;

  constructor(container: HTMLElement) {
    this.container = container;
    this.updateFocusableElements();
  }

  private updateFocusableElements(): void {
    this.focusableElements = getFocusableElements(this.container);
    this.firstFocusableElement = this.focusableElements[0] || null;
    this.lastFocusableElement = this.focusableElements[this.focusableElements.length - 1] || null;
  }

  private handleKeyDown = (event: KeyboardEvent): void => {
    if (event.key !== 'Tab') return;

    this.updateFocusableElements();

    if (this.focusableElements.length === 0) {
      event.preventDefault();
      return;
    }

    if (event.shiftKey) {
      // Shift + Tab (backward)
      if (document.activeElement === this.firstFocusableElement) {
        event.preventDefault();
        this.lastFocusableElement?.focus();
      }
    } else {
      // Tab (forward)
      if (document.activeElement === this.lastFocusableElement) {
        event.preventDefault();
        this.firstFocusableElement?.focus();
      }
    }
  };

  public activate(): void {
    this.previouslyFocusedElement = document.activeElement as HTMLElement;
    this.container.addEventListener('keydown', this.handleKeyDown);
    
    // Focus the first focusable element
    if (this.firstFocusableElement) {
      this.firstFocusableElement.focus();
    }
  }

  public deactivate(): void {
    this.container.removeEventListener('keydown', this.handleKeyDown);
    
    // Return focus to previously focused element
    if (this.previouslyFocusedElement) {
      this.previouslyFocusedElement.focus();
    }
  }
}

/**
 * Creates a focus trap for a modal or dialog
 */
export const createFocusTrap = (container: HTMLElement): FocusTrap => {
  return new FocusTrap(container);
};

/**
 * Manages focus for roving tabindex (useful for lists and grids)
 */
export class RovingTabIndex {
  private container: HTMLElement;
  private items: HTMLElement[] = [];
  private currentIndex: number = 0;

  constructor(container: HTMLElement, itemSelector: string) {
    this.container = container;
    this.updateItems(itemSelector);
    this.setupEventListeners();
  }

  private updateItems(itemSelector: string): void {
    this.items = Array.from(this.container.querySelectorAll(itemSelector)) as HTMLElement[];
    this.updateTabIndices();
  }

  private updateTabIndices(): void {
    this.items.forEach((item, index) => {
      item.tabIndex = index === this.currentIndex ? 0 : -1;
    });
  }

  private handleKeyDown = (event: KeyboardEvent): void => {
    const { key } = event;
    let newIndex = this.currentIndex;

    switch (key) {
      case 'ArrowDown':
      case 'ArrowRight':
        event.preventDefault();
        newIndex = (this.currentIndex + 1) % this.items.length;
        break;
      case 'ArrowUp':
      case 'ArrowLeft':
        event.preventDefault();
        newIndex = this.currentIndex === 0 ? this.items.length - 1 : this.currentIndex - 1;
        break;
      case 'Home':
        event.preventDefault();
        newIndex = 0;
        break;
      case 'End':
        event.preventDefault();
        newIndex = this.items.length - 1;
        break;
      default:
        return;
    }

    this.setCurrentIndex(newIndex);
  };

  private setupEventListeners(): void {
    this.container.addEventListener('keydown', this.handleKeyDown);
    
    this.items.forEach((item, index) => {
      item.addEventListener('focus', () => {
        this.setCurrentIndex(index);
      });
    });
  }

  public setCurrentIndex(index: number): void {
    if (index >= 0 && index < this.items.length) {
      this.currentIndex = index;
      this.updateTabIndices();
      if (this.items[index]) {
        this.items[index].focus();
      }
    }
  }

  public destroy(): void {
    this.container.removeEventListener('keydown', this.handleKeyDown);
  }
}

/**
 * Creates a roving tabindex for a container
 */
export const createRovingTabIndex = (
  container: HTMLElement, 
  itemSelector: string
): RovingTabIndex => {
  return new RovingTabIndex(container, itemSelector);
};

/**
 * Announces text to screen readers
 */
export const announceToScreenReader = (
  message: string, 
  priority: 'polite' | 'assertive' = 'polite'
): void => {
  const announcement = document.createElement('div');
  announcement.setAttribute('aria-live', priority);
  announcement.setAttribute('aria-atomic', 'true');
  announcement.className = 'sr-only';
  announcement.textContent = message;

  document.body.appendChild(announcement);

  // Remove the announcement after a short delay
  setTimeout(() => {
    document.body.removeChild(announcement);
  }, 1000);
};

/**
 * Creates a live region for dynamic content announcements
 */
export const createLiveRegion = (
  id: string, 
  priority: 'polite' | 'assertive' = 'polite'
): HTMLElement => {
  let liveRegion = document.getElementById(id);
  
  if (!liveRegion) {
    liveRegion = document.createElement('div');
    liveRegion.id = id;
    liveRegion.setAttribute('aria-live', priority);
    liveRegion.setAttribute('aria-atomic', 'true');
    liveRegion.className = 'sr-only';
    document.body.appendChild(liveRegion);
  }

  return liveRegion;
};

/**
 * Updates a live region with new content
 */
export const updateLiveRegion = (id: string, message: string): void => {
  const liveRegion = document.getElementById(id);
  if (liveRegion) {
    liveRegion.textContent = message;
  }
};

/**
 * Manages skip links for keyboard navigation
 */
export const createSkipLink = (
  targetId: string, 
  text: string = 'Skip to main content'
): HTMLElement => {
  const skipLink = document.createElement('a');
  skipLink.href = `#${targetId}`;
  skipLink.textContent = text;
  skipLink.className = 'skip-link';
  
  skipLink.addEventListener('click', (event) => {
    event.preventDefault();
    const target = document.getElementById(targetId);
    if (target) {
      target.focus();
      target.scrollIntoView({ behavior: 'smooth' });
    }
  });

  return skipLink;
};

/**
 * Ensures an element is focusable and focuses it
 */
export const focusElement = (element: HTMLElement): void => {
  if (!element.hasAttribute('tabindex')) {
    element.tabIndex = -1;
  }
  element.focus();
};

/**
 * Restores focus to a previously focused element
 */
export const restoreFocus = (element: HTMLElement | null): void => {
  if (element && document.contains(element)) {
    element.focus();
  }
};

/**
 * Checks if an element is currently visible and focusable
 */
export const isElementFocusable = (element: HTMLElement): boolean => {
  if (element.hidden || element.hasAttribute('disabled')) {
    return false;
  }

  const style = window.getComputedStyle(element);
  if (style.display === 'none' || style.visibility === 'hidden') {
    return false;
  }

  const rect = element.getBoundingClientRect();
  return rect.width > 0 && rect.height > 0;
};

/**
 * Gets the next/previous focusable sibling
 */
export const getFocusableSibling = (
  element: HTMLElement, 
  direction: 'next' | 'previous'
): HTMLElement | null => {
  const parent = element.parentElement;
  if (!parent) return null;

  const focusableElements = getFocusableElements(parent);
  const currentIndex = focusableElements.indexOf(element);
  
  if (currentIndex === -1) return null;

  if (direction === 'next') {
    return focusableElements[currentIndex + 1] || null;
  } else {
    return focusableElements[currentIndex - 1] || null;
  }
};